from robot.libraries.BuiltIn import BuiltIn


def count_if(items, condition):
    value = 0
    for item in items:
        if condition(item):
            value += 1
    return value


class lazy_import(object):
    """
    When one tries to use python library which uses get_library_instance("some_lib") (e.g. in __init__) before it was
    imported in .robot file "No library 'some_lib' found" error will occur. This class solves problem of imports order
    by delaying get_library_instance method call till it is needed.
    """

    def __init__(self, lib_name):
        self.lib_name = lib_name
        self.imported = None

    def __getattr__(self, method):
        if self.imported is None:
            self.imported = BuiltIn().get_library_instance(self.lib_name)
        return getattr(self.imported, method)
